import { InterestTag, TraitKey } from './types';

export type GiftTier = '20' | '50' | '100';

/** Dimensions structurées décrivant un produit — remplace `tags` (libre) pour les thèmes migrés
 *  vers la vraie taxonomie (voir plan de refonte "moteur de réduction progressive"). Les clés sont
 *  libres et propres à chaque thème (ex. gaming: primaryUse/equipmentLevel, animaux: typeAnimal),
 *  elles doivent juste reprendre exactement les ids de question de themeQuizzes.ts pour ce thème —
 *  le moteur de scoring ne compare que les VALEURS, pas les noms de dimension (voir
 *  taxonomyMatchCount dans recommendationEngine.ts). */
export type GiftTaxonomy = Partial<Record<string, string[]>>;

export type CuratedGift = {
  /** CHANTIER "Cadeaux V2 — Phase 6B" (2026-09-21) — identifiant CANONIQUE Pensif, obligatoire et
   *  stable : c'est désormais la seule clé utilisée pour l'identité d'un produit dans tout le
   *  moteur/UI/historique/feedback (voir recommendationEngine.ts `giftById`) — `asin` n'est plus
   *  jamais utilisé comme clé, uniquement comme donnée commerce Amazon optionnelle (voir plus bas).
   *  Ne JAMAIS réutiliser un `id` déjà attribué à un autre produit, même après suppression : les
   *  contacts existants peuvent encore y faire référence dans `feedback`/`recommendationHistory`. */
  id: string;
  theme: InterestTag;
  /** Indicatif seulement (héritage des 3 paliers d'origine) — le moteur de recommandation score
   *  par `price` réel contre le budget demandé, il ne sélectionne plus par palier fixe. */
  tier: GiftTier;
  title: string;
  /** CHANTIER "Phase 6B" (2026-09-21) — donnée COMMERCE Amazon, désormais optionnelle : un produit
   *  sans ASIN (catalogue "safe beta" sans sourcing commercial, voir Phase 5F/5G) reste scorable et
   *  recommandable normalement, simplement sans lien "Voir sur Amazon" ni photo produit (voir
   *  GiftsScreen.tsx). Ne sert plus JAMAIS d'identité — voir `id`. */
  asin?: string;
  /** Prix de référence ÉDITORIAL utilisé par Pensif pour le filtrage budget, le tri (tie-break) et
   *  certains bonus de scoring (voir generateCandidates/genericThemeAnswerBonus dans
   *  recommendationEngine.ts) — PAS une garantie de prix marchand live (le prix Amazon réel peut
   *  varier). Reste obligatoire dans cette passe (voir consigne Phase 6B §9) : aucun `merchantPrice`
   *  distinct introduit ici. */
  price: number;
  emoji: string;
  /** URL de la vraie image produit (extraite de la fiche Amazon — data-old-hires), pas une URL
   *  devinée : l'ancien format "legacy" (/images/P/{asin}...) ne fonctionne que par coïncidence
   *  pour certains ASIN et renvoie une image vide/placeholder pour les autres sans jamais déclencher
   *  d'erreur réseau, d'où les fonds vides observés. Chaque produit stocke maintenant l'URL réelle
   *  de son image (/images/I/{id}...), vérifiée le 2026-09-11 avec le titre/prix/stock.
   *  CHANTIER "Phase 6B" (2026-09-21) — désormais optionnelle : absente ⇒ repli emoji dans
   *  GiftsScreen.tsx, jamais d'URL devinée/fabriquée. */
  imageUrl?: string;
  /** Description courte de l'OBJET lui-même — un vrai pitch produit ("pourquoi c'est utile de
   *  l'avoir"), pas une phrase sur le contact. C'est le texte principal affiché sous chaque
   *  recommandation (voir whyForContact dans recommendationEngine.ts), qui n'ajoute qu'une courte
   *  clause de personnalisation à la fin, seulement quand un signal concret le justifie. */
  pitch: string;
  /** Trait de personnalité auquel ce produit correspond le mieux (voir computeTraits dans
   *  quiz.ts) — utilisé par le moteur de recommandation pour bonifier les produits alignés avec
   *  le portrait du contact. */
  trait?: TraitKey;
  /** Clés libres recoupant les réponses d'affinage par thème (voir themeQuizzes.ts) — mécanisme
   *  historique, encore utilisé par les thèmes pas encore migrés vers `taxonomy`. Purement un
   *  bonus de score, jamais éliminatoire. */
  tags?: string[];
  /** Dimensions structurées (remplace `tags` pour les thèmes migrés) — chaque valeur qui recoupe
   *  une réponse d'affinage ajoute un bonus de score, sans jamais éliminer le produit. */
  taxonomy?: GiftTaxonomy;
  /** Filtre DUR : si le contact a répondu à CETTE question (clé = id de question, ex. 'platform')
   *  et que sa réponse n'est dans AUCUNE des valeurs listées ici, le produit est éliminé du pool —
   *  pas juste pénalisé. Ex. { platform: ['playstation'] } sur une manette DualSense : disparaît
   *  dès que le contact a répondu Xbox. Absence de réponse à cette question = pas de filtre (on ne
   *  sait pas encore, donc on ne prive pas). */
  hardRequirements?: Record<string, string[]>;
  /** Filtre DUR inverse : éliminé si la réponse du contact à cette question EST une des valeurs
   *  listées ici. */
  hardExclusions?: Record<string, string[]>;
  /** Idée-cadeau concrète (ex. 'mouse', 'coffee-grinder') — distincte de `taxonomy` : deux souris
   *  gaming de marques différentes ont la même taxonomy mais le MÊME giftConcept, donc ne comptent
   *  que comme une seule idée dans l'audit de diversité (voir scripts/audit-catalog.js). Un chemin
   *  avec beaucoup de produits mais un seul giftConcept est un faux catalogue riche. */
  giftConcept?: string;
  /** CHANTIER "Quiz Cadeaux V2 — Phase 1" (2026-09-21) — concepts canoniques FACTUELLEMENT associés
   *  à ce produit précis (licence, franchise, marque, jeu, artiste, équipe, univers…) : toujours des
   *  slugs canoniques (voir canonicalize()/toCanonicalConcept() dans textSignals.ts), ex. 'lego',
   *  'pokemon', 'playstation'. Rempli UNIQUEMENT quand le nom apparaît littéralement dans `title`
   *  (jamais déduit de la description ni d'une association plausible) — voir l'audit du catalogue
   *  pour la méthode exacte. Comparé au texte libre du quiz (wish/favorite/detail) par
   *  entityMatchBonus() dans recommendationEngine.ts : un bonus fort et explicite, jamais un filtre,
   *  jamais un faux positif inventé quand aucun produit ne porte l'entity demandée (voir le cas
   *  "Star Wars" dans le rapport de chantier — aucun produit du catalogue actuel ne porte
   *  `star_wars`, donc aucun bonus, jamais fabriqué). */
  entities?: string[];
};

const AMAZON_TAG = 'pensif-21';

export function amazonUrl(asin: string): string {
  return `https://www.amazon.fr/dp/${asin}?tag=${AMAZON_TAG}`;
}

